1\", className)} /\u003e;\n}\n\nexport interface ColorSelectorItemProps extends Omit\u003cComponentPropsWithRef\u003c\"input\"\u003e, \"type\" | \"value\" | \"defaultValue\" | \"checked\" | \"defaultChecked\" | \"name\" | \"children\" | \"size\"\u003e {\n  value: string;\n  /** Any CSS color, including a custom property. */\n  color: string;\n  /** Accessible color name; selection never relies on color alone. */\n  label: string;\n  /** Applied to the visible swatch surface. */\n  className?: string;\n}\n\nexport function ColorSelectorItem({ value, color, label, disabled = false, className, style, onChange, ...props }: ColorSelectorItemProps) {\n  const context = useContext(ColorSelectorContext);\n  const reduce = useReducedMotion();\n  if (!context) throw new Error(\"ColorSelectorItem must be used within ColorSelector\");\n  const selected = context.value === value;\n  const unavailable = disabled || context.disabled;\n  return (\n    \u003cmotion.label\n      tabIndex={-1}\n      whileTap={reduce || unavailable ? undefined : { scale: 0.94 }}\n      transition={SPRING_PRESS}\n      className={cn(\"relative inline-flex shrink-0 rounded-full\", unavailable ? \"cursor-not-allowed opacity-40\" : \"cursor-pointer\")}\u003e\n      \u003cinput\n        {...props}\n        type=\"radio\"\n        name={context.name}\n        value={value}\n        checked={selected}\n        disabled={unavailable}\n        required={context.required}\n        form={context.form}\n        aria-label={label}\n        onChange={(event) =\u003e {\n          onChange?.(event);\n          if (!event.defaultPrevented) context.select(value);\n        }}\n        className=\"peer sr-only\"\n      /\u003e\n      \u003cspan\n        aria-hidden=\"true\"\n        style={style}\n        className={cn(\n          \"relative flex size-11 items-center justify-center rounded-full border border-foreground/10 bg-muted/60\",\n          \"peer-focus-visible:outline-2 peer-focus-visible:outline-offset-4 peer-focus-visible:outline-foreground\",\n          className,\n        )}\n      \u003e\n        {selected \u0026\u0026 (\n          \u003cmotion.span\n            layoutId={reduce ? undefined : \"color-selection\"}\n            initial={false}\n            transition={SELECTION_HOP}\n            className=\"pointer-events-none absolute -inset-1 rounded-full border-2\"\n            style={{ borderColor: `color-mix(in srgb, ${color} 65%, transparent)` }}\n          /\u003e\n        )}\n        \u003cspan className=\"size-5 rounded-full border border-black/5\" style={{ backgroundColor: color }} /\u003e\n      \u003c/span\u003e\n    \u003c/motion.label\u003e\n  );\n}\n50:[\"$\",\"div\",\"components/motion/color-selector.tsx\",{\"className\":\"group relative overflow-hidden rounded-xl border border-border bg-card font-mono text-[13px]\",\"children\":[[\"$\",\"div\",null,{\"className\":\"flex items-center justify-between gap-3 border-b border-border bg-background/60 px-4 py-2.5\",\"children\":[[\"$\",\"div\",null,{\"className\":\"flex min-w-0 items-center gap-2 text-xs\",\"children\":[[\"$\",\"span\",null,{\"className\":\"inline-flex h-5 shrink-0 items-center rounded border border-border bg-card px-1.5 font-mono text-[10px] font-semibold tracking-wider text-muted-foreground uppercase\",\"children\":\"TSX\"}],[\"$\",\"$L21\",null,{\"ref\":\"$undefined\",\"iconNode\":\"$44:props:children:0:props:children:0:props:children:1:props:iconNode\",\"className\":\"lucide-file h-3.5 w-3.5 shrink-0 text-muted-foreground\"}],[\"$\",\"span\",null,{\"className\":\"truncate font-mono text-muted-foreground\",\"children\":[[\"$\",\"span\",null,{\"className\":\"text-foreground\",\"children\":[\"components/motion\",\"/\"]}],[\"$\",\"span\",null,{\"className\":\"text-foreground font-medium\",\"children\":\"color-selector.tsx\"}]]}]]}],[\"$\",\"$L46\",null,{\"text\":\"$54\",\"eventLabel\":\"components/motion/color-selector.tsx\"}]]}],\"$L55\"]}]\n56:T6c9b,\u003cstyle\u003e.k1orcrl{--shiki-light:#032